include <robotics.scad>
// Teensy 4.1 PCB, origin at board centre on the bottom face. USB end = -X.
L = 60.96; W = 17.78; T = 1.57;
p = 2.54;                 // header pitch
d_pin = 0.965;            // finished hole, 59 holes
d_eth = 0.762;            // finished hole, 6 Ethernet holes
x0 = -L/2;                // USB edge
x1 = x0 + 1.27;           // pin-1 centre (datum for drawing X dims)
yT = W/2;                 // top edge (drawing top = +Y)

module hole(x, y, d) translate([x, y, -1]) cylinder(d = d, h = T + 2, $fn = 24);

difference() {
  translate([0, 0, T/2]) cube([L, W, T], center = true);
  // two 24-pin edge rows, 15.24 apart
  for (i = [0:23], s = [-1, 1]) hole(x1 + i*p, s*7.62, d_pin);
  // extra pin: pin-2 column, 2.54 inside the top row
  hole(x1 + p, 7.62 - p, d_pin);
  // USB host 5-pin: centre 11.43 from pin 1, 3.05 above bottom row
  for (k = [-2:2]) hole(x1 + 11.43 + k*p, -7.62 + 3.05, d_pin);
  // inner 5-pin column: 45.72 from pin 1, centred
  for (k = [-2:2]) hole(x1 + 45.72, k*p, d_pin);
  // Ethernet 6-pin, 2.0 pitch: centre 13.97 from pin 1, middle row 4.45 below top row
  for (cx = [-1, 1], ry = [-1, 0, 1]) hole(x1 + 13.97 + cx*1.0, 7.62 - 4.45 + ry*2.0, d_eth);
}

include <robotics.scad>
// Origin: PCB USB edge (x=0), board centreline, PCB top face. Board extends +X.
tip = 0.7;  plate_t = 0.6;  plate_w = 8.06;  plate_h = 3.07;
body_l = 5.0;  body_w = 7.5;  body_h = 2.5;
union() {
  // front plate / flange: from tip to 0.6 behind it, top flush with body top
  translate([-tip, -plate_w/2, body_h - plate_h]) cube([plate_t, plate_w, plate_h]);
  // shell body sitting on the PCB
  translate([-tip + plate_t, -body_w/2, 0]) cube([body_l, body_w, body_h]);
}

include <robotics.scad>
// Origin: button centre on PCB top face.
base = [4.7, 3.2, 1.8];   // footprint scaled from drawing; height dimensioned
cap  = [3.0, 2.0];        // width dimensioned; depth scaled
top_h = 2.5;              // dimensioned overall height above PCB
translate([-base.x/2, -base.y/2, 0]) cube(base);
translate([-cap.x/2, -cap.y/2, base.z - 0.01]) cube([cap.x, cap.y, top_h - base.z + 0.01]);
